// ---------------------------------------------------------------
// Normalize the request coming from Retell.
//
// Retell can deliver a Custom Function payload in more than one shape
// depending on how the Function node is configured:
//   { "args": { ... }, "name": "...", "call": { ... } }   <- most common
//   { ... fields at top level ... }                          <- raw body mode
// n8n additionally wraps the HTTP body in `body`.
// We flatten all of that here ONCE so every node downstream can just
// use $json.action, $json.policy_number, etc.
//
// We also repair the two identifiers that a speech-to-text engine is
// most likely to mangle:
//   "pol one oh two three four" / "POL 10234" / "pol-10234" -> POL-10234
//   "claim 42" / "CLM 42"                                   -> CLM-000042
// Doing this server-side means the agent never has to be perfect.
// ---------------------------------------------------------------

const raw = $json.body ?? $json;
const a = raw.args ?? raw;

const str = (v) => (v === undefined || v === null ? '' : String(v).trim());
const digitsOnly = (v) => str(v).replace(/\D/g, '');

function normalisePolicy(v) {
  const d = digitsOnly(v);
  return d ? `POL-${d}` : '';
}

function normaliseClaim(v) {
  const d = digitsOnly(v);
  return d ? `CLM-${d.padStart(6, '0')}` : '';
}

return [
  {
    json: {
      sheet_id: $json.sheet_id,
      action: str(a.action).toLowerCase(),
      policy_number: normalisePolicy(a.policy_number),
      claim_id: normaliseClaim(a.claim_id),
      holder_name: str(a.holder_name || a.name),
      incident_type: str(a.incident_type),
      incident_date: str(a.incident_date),
      description: str(a.description),
      email: str(a.email).toLowerCase(),
      urgency_hint: str(a.urgency),
      raw_policy_number: str(a.policy_number),
      raw_claim_id: str(a.claim_id)
    }
  }
];

// ---------------------------------------------------------------
// Shape the validate_policy answer for the voice agent.
//
// Three possible outcomes, all returned as HTTP 200 so Retell always
// gets something it can speak. Errors are expressed in the payload,
// never as an HTTP error code -- a 4xx/5xx would make the agent say
// "something went wrong" instead of "I couldn't find that policy".
// ---------------------------------------------------------------

const asked = $('Normalize Request').first().json;
const row = $json || {};
const found = Boolean(row.policy_number);

if (!found) {
  return [
    {
      json: {
        valid: false,
        result: 'not_found',
        reason: 'not_found',
        policy_number: asked.policy_number,
        message: `No policy found matching ${asked.policy_number}.`
      }
    }
  ];
}

// Expiry check: a policy that exists but has lapsed is not a valid
// policy to file a claim against, and the agent should say so plainly.
const validUntil = String(row.valid_until || '').trim();
const expiryDate = validUntil ? new Date(`${validUntil}T23:59:59Z`) : null;
const expired = expiryDate && !isNaN(expiryDate) && expiryDate < new Date();

if (expired) {
  return [
    {
      json: {
        valid: false,
        result: 'expired',
        reason: 'expired',
        policy_number: row.policy_number,
        holder_name: row.holder_name,
        coverage_type: row.coverage_type,
        valid_until: validUntil,
        message: `Policy ${row.policy_number} expired on ${validUntil}.`
      }
    }
  ];
}

return [
  {
    json: {
      valid: true,
      result: 'valid',
      reason: 'ok',
      policy_number: row.policy_number,
      holder_name: row.holder_name,
      coverage_type: row.coverage_type,
      valid_until: validUntil,
      message: `Policy ${row.policy_number} is active and held by ${row.holder_name}.`
    }
  }
];

// ---------------------------------------------------------------
// 1. Generate the claim ID.
// 2. Re-run urgency triage server-side.
//
// Why triage here and not only in the conversation flow: an LLM
// deciding "is this urgent?" is a judgement call that can change
// between runs. A keyword rule is deterministic -- the same words
// always produce the same urgency, which is what you want on a record
// that drives an SLA (24-48h vs 5-7 business days per the policy FAQ).
// The flow's own guess arrives as `urgency_hint`; we let it escalate
// to Urgent but never let it downgrade an Urgent to Standard.
// ---------------------------------------------------------------

const d = $json;

// CLM- plus the last 6 digits of the epoch millisecond clock.
// Monotonic, collision-free at demo call volumes, and short enough for
// the agent to read aloud digit by digit without losing the caller.
const claimId = `CLM-${String(Date.now()).slice(-6)}`;

const URGENT_KEYWORDS = [
  'injur', 'injured', 'hurt', 'wound', 'bleed', 'blood', 'broken bone',
  'fracture', 'hospital', 'ambulance', 'emergency', 'er ', 'icu',
  'surgery', 'unconscious', 'concussion', 'paramedic',
  'fire', 'burn', 'burning', 'smoke', 'explosion', 'flood', 'flooding',
  'gas leak', 'collapse', 'structural damage', 'totaled', 'total loss',
  'write-off', 'life threatening', 'life-threatening', 'critical',
  'death', 'died', 'fatal'
];

const haystack = `${d.description} ${d.incident_type}`.toLowerCase();
const matched = URGENT_KEYWORDS.filter((k) => haystack.includes(k));

const hintIsUrgent = String(d.urgency_hint || '').toLowerCase() === 'urgent';
const urgency = matched.length > 0 || hintIsUrgent ? 'Urgent' : 'Standard';

// Google Sheets stores plain strings; format the timestamp the same way
// the provided Claims-Template.csv does (YYYY-MM-DD HH:mm) so the
// Streamlit dashboard can parse the whole column with one format.
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const createdAt =
  `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ` +
  `${pad(now.getHours())}:${pad(now.getMinutes())}`;

return [
  {
    json: {
      claim_id: claimId,
      policy_number: d.policy_number,
      holder_name: d.holder_name,
      incident_type: d.incident_type || 'Other',
      incident_date: d.incident_date,
      description: d.description,
      urgency,
      status: 'Filed',
      email: d.email,
      created_at: createdAt,
      triage_matched_keywords: matched.join(', ')
    }
  }
];

// Return only what the agent needs to speak. The caller does not need
// to hear the row index or the keyword list, and every extra field is
// another thing the model can decide to read out loud.
const c = $('Generate Claim ID & Triage').first().json;

return [
  {
    json: {
      success: true,
      result: c.urgency === 'Urgent' ? 'urgent' : 'standard',
      claim_id: c.claim_id,
      urgency: c.urgency,
      status: c.status,
      holder_name: c.holder_name,
      incident_type: c.incident_type,
      message:
        c.urgency === 'Urgent'
          ? `Claim ${c.claim_id} has been filed and flagged as urgent for priority review within 24 to 48 hours.`
          : `Claim ${c.claim_id} has been filed and will be reviewed within 5 to 7 business days.`
    }
  }
];

// ---------------------------------------------------------------
// Shape the check_status answer.
//
// `found: false` is a normal, expected outcome, not an error --
// the conversation flow branches on it to offer a retry or a handoff.
// ---------------------------------------------------------------

const asked = $('Normalize Request').first().json;
const row = $json || {};

if (!row.claim_id) {
  return [
    {
      json: {
        found: false,
        result: 'not_found',
        claim_id: asked.claim_id,
        message: `No claim found with ID ${asked.claim_id}.`
      }
    }
  ];
}

return [
  {
    json: {
      found: true,
      result: 'found',
      claim_id: row.claim_id,
      status: row.status,
      incident_type: row.incident_type,
      urgency: row.urgency,
      holder_name: row.holder_name,
      incident_date: row.incident_date,
      created_at: row.created_at,
      message: `Claim ${row.claim_id} for a ${row.incident_type} incident is currently ${row.status}.`
    }
  }
];
